/**
 * LLM Proxy — OpenAI-compatible endpoint for sandbox-internal LLM calls.
 *
 * Following the Manus pattern: code running inside E2B sandboxes calls this
 * proxy using OPENAI_API_KEY + OPENAI_BASE_URL. The proxy forwards to the
 * real OpenAI API (or other providers), authenticating with our server-side key.
 *
 * Endpoints:
 *   POST /api/llm-proxy/v1/chat/completions — Proxy chat completions
 *   GET  /api/llm-proxy/v1/models           — List available models
 *
 * Auth: Bearer token in Authorization header — must be a valid sandbox proxy token
 * (rk_sbx_<random>) generated by the orchestrator when creating a sandbox.
 *
 * Blocked models: Claude (prevents recursive self-invocation from sandbox).
 */

import type { FastifyInstance } from "fastify";
import { createLogger } from "@repo/service-utils";
import { validateProxyToken } from "../lib/e2b-manager.js";

const logger = createLogger({ service: "llm-proxy" });

const OPENAI_API_KEY = process.env.OPENAI_API_KEY || "";
const OPENAI_BASE_URL = "https://api.openai.com/v1";

// Models blocked from sandbox use (prevent recursive self-invocation)
const BLOCKED_MODEL_PREFIXES = [
  "claude",
  "anthropic",
];

// Models explicitly allowed through the proxy
const ALLOWED_MODELS = [
  "gpt-4o",
  "gpt-4o-mini",
  "gpt-4.1",
  "gpt-4.1-mini",
  "gpt-4.1-nano",
  "gpt-3.5-turbo",
  "o1",
  "o1-mini",
  "o1-preview",
  "o3-mini",
];

function isModelBlocked(model: string): boolean {
  const lower = model.toLowerCase();
  return BLOCKED_MODEL_PREFIXES.some((prefix) => lower.startsWith(prefix));
}

function extractBearerToken(authHeader: string | undefined): string | null {
  if (!authHeader) return null;
  const parts = authHeader.split(" ");
  if (parts.length !== 2 || parts[0] !== "Bearer") return null;
  return parts[1] || null;
}

export async function llmProxyRoutes(app: FastifyInstance) {
  // ─── POST /api/llm-proxy/v1/chat/completions ───────────────────────────
  app.post("/api/llm-proxy/v1/chat/completions", async (request, reply) => {
    // Validate auth
    const token = extractBearerToken(request.headers.authorization);
    if (!token) {
      return reply.status(401).send({
        error: {
          message: "Missing or invalid Authorization header. Expected: Bearer <token>",
          type: "invalid_request_error",
          code: "invalid_api_key",
        },
      });
    }

    // Validate proxy token against known sandbox tokens
    const tokenInfo = validateProxyToken(token);
    if (!tokenInfo) {
      logger.warn({ tokenPrefix: token.substring(0, 12) }, "LLM proxy: invalid proxy token");
      return reply.status(401).send({
        error: {
          message: "Invalid API key. The provided sandbox proxy token is not recognized.",
          type: "invalid_request_error",
          code: "invalid_api_key",
        },
      });
    }

    if (!OPENAI_API_KEY) {
      return reply.status(503).send({
        error: {
          message: "LLM proxy not configured: OPENAI_API_KEY not set",
          type: "server_error",
          code: "service_unavailable",
        },
      });
    }

    const body = request.body as Record<string, unknown>;
    const model = (body.model as string) || "gpt-4o-mini";

    // Block Claude models — prevent recursive self-invocation
    if (isModelBlocked(model)) {
      return reply.status(400).send({
        error: {
          message: `Model "${model}" is not available through the LLM proxy. Claude models cannot be called from inside sandboxes to prevent recursive invocation.`,
          type: "invalid_request_error",
          code: "model_not_available",
        },
      });
    }

    const isStreaming = body.stream === true;

    logger.info(
      {
        model,
        streaming: isStreaming,
        messageCount: Array.isArray(body.messages) ? body.messages.length : 0,
        sandboxId: tokenInfo.sandboxId,
        userId: tokenInfo.userId,
      },
      "LLM proxy: forwarding request"
    );

    try {
      const upstreamResp = await fetch(`${OPENAI_BASE_URL}/chat/completions`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${OPENAI_API_KEY}`,
        },
        body: JSON.stringify(body),
      });

      // Forward status code
      reply.status(upstreamResp.status);

      // Forward content-type and other relevant headers
      const contentType = upstreamResp.headers.get("content-type");
      if (contentType) {
        reply.header("Content-Type", contentType);
      }

      // Stream or return JSON
      if (isStreaming && upstreamResp.body) {
        reply.header("Cache-Control", "no-cache");
        reply.header("Connection", "keep-alive");

        // Pipe the upstream SSE stream directly to the client
        const reader = upstreamResp.body.getReader();
        const stream = new ReadableStream({
          async pull(controller) {
            const { done, value } = await reader.read();
            if (done) {
              controller.close();
              return;
            }
            controller.enqueue(value);
          },
        });

        return reply.send(stream);
      }

      // Non-streaming: forward JSON response
      const data = await upstreamResp.json();
      return reply.send(data);
    } catch (error) {
      const errMsg = error instanceof Error ? error.message : "Unknown error";
      logger.error({ error: errMsg }, "LLM proxy: upstream request failed");

      return reply.status(502).send({
        error: {
          message: `LLM proxy upstream error: ${errMsg}`,
          type: "server_error",
          code: "upstream_error",
        },
      });
    }
  });

  // ─── GET /api/llm-proxy/v1/models ──────────────────────────────────────
  app.get("/api/llm-proxy/v1/models", async (request, reply) => {
    // Validate auth
    const token = extractBearerToken(request.headers.authorization);
    if (!token) {
      return reply.status(401).send({
        error: {
          message: "Missing or invalid Authorization header",
          type: "invalid_request_error",
          code: "invalid_api_key",
        },
      });
    }

    // Validate proxy token
    const tokenInfo = validateProxyToken(token);
    if (!tokenInfo) {
      return reply.status(401).send({
        error: {
          message: "Invalid API key. The provided sandbox proxy token is not recognized.",
          type: "invalid_request_error",
          code: "invalid_api_key",
        },
      });
    }

    // Return our allowed model list in OpenAI format
    return reply.send({
      object: "list",
      data: ALLOWED_MODELS.map((id) => ({
        id,
        object: "model",
        created: Math.floor(Date.now() / 1000),
        owned_by: "rubic-proxy",
      })),
    });
  });

  // ─── Health check ──────────────────────────────────────────────────────
  app.get("/api/llm-proxy/v1/health", async (_request, reply) => {
    return reply.send({
      status: "ok",
      configured: !!OPENAI_API_KEY,
      allowedModels: ALLOWED_MODELS,
      blockedPrefixes: BLOCKED_MODEL_PREFIXES,
    });
  });
}
